// src/agents/LeadMiningAgent.ts
import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { globalPythonShell } from '../utils/pythonShell.js';
import { logInfo, logError } from '../utils/logger.js';
import { toolManager } from '../server/ToolManager.js';
import { updateBusinessJobStatus } from '../utils/db.js';

export class LeadMiningAgent extends BaseAgent {
    name = "lead_mining";
    role = "Lead Mining Service";
    description = "Generates targeted B2B lead lists with icebreakers.";
    capabilities = ["lead_generation", "web_scraping", "icebreaker_generation"];

    async executeTask(context: AgentContext): Promise<AgentResult> {
        const query = context.task || "fogorvos Budapest";
        const jobId = (context as any).jobId;

        logInfo(this.name, `Starting lead mining for: ${query} (Job: ${jobId || 'N/A'})`);

        if (jobId) {
            await updateBusinessJobStatus(jobId, 'running');
        }

        try {
            // 1. Scrape businesses using Apify (compass/crawler-google-places)
            logInfo(this.name, `Calling Apify Crawler for: ${query}`);

            // Parsing query to split between search term and location if possible
            // Format example: "fogorvos Budapest" -> search: "fogorvos", location: "Budapest"
            const queryParts = query.split(' ');
            const location = queryParts.length > 1 ? queryParts.pop() : "Budapest";
            const searchTerm = queryParts.join(' ') || "fogorvos";

            const scrapeResult = await toolManager.executeTool('compass-slash-crawler-google-places', {
                searchStringsArray: [searchTerm],
                locationQuery: location,
                maxCrawledPlacesPerSearch: 5
            });

            // The tool result structure might vary, we assume it's an array or has a data field
            let leads = [];
            if (Array.isArray(scrapeResult)) {
                leads = scrapeResult;
            } else if (scrapeResult && typeof scrapeResult === 'object' && (scrapeResult as any).data) {
                leads = (scrapeResult as any).data;
            } else if (scrapeResult && typeof scrapeResult === 'object' && (scrapeResult as any).items) {
                leads = (scrapeResult as any).items;
            }

            if (!leads || leads.length === 0) {
                if (jobId) await updateBusinessJobStatus(jobId, 'failed', JSON.stringify({ error: "No leads found" }));
                return { success: false, message: "Nem találtam lead-eket az adott keresésre." };
            }

            // 2. Generate icebreakers for each lead using Python worker
            logInfo(this.name, `Generating icebreakers for ${leads.length} leads...`);
            const enrichedLeads = [];

            for (const lead of leads) {
                try {
                    const companyName = lead.title || lead.name || "Ismeretlen cég";
                    const website = lead.website || "Nincs weboldal";

                    const icebreakerCode = `
from myai.workers.icebreaker_generator import generate_icebreaker
import asyncio
import json

async def run():
    ctx = """${companyName} - ${website}"""
    ib = await generate_icebreaker(ctx)
    print(json.dumps(ib))

asyncio.run(run())
                    `;
                    const ibOutput = await globalPythonShell.run(icebreakerCode);
                    const icebreaker = JSON.parse(ibOutput);

                    enrichedLeads.push({
                        id: lead.placeId || lead.id || Math.random().toString(36).substr(2, 9),
                        name: companyName,
                        website: website,
                        industry: lead.categoryName || lead.industry || "General",
                        address: lead.address || lead.fullAddress || "N/A",
                        phone: lead.phoneNumber || lead.phone || "N/A",
                        icebreaker: icebreaker
                    });
                } catch (e) {
                    logError(this.name, `Failed to enrich lead: ${lead.title || lead.name}`);
                    enrichedLeads.push({
                        ...lead,
                        icebreaker: "Szia! Láttam a vállalkozásodat a Google Maps-en, és nagyon tetszik amit csináltok!"
                    });
                }
            }

            // 3. Finalize Job
            if (jobId) {
                await updateBusinessJobStatus(jobId, 'completed', JSON.stringify(enrichedLeads));
            }

            logInfo(this.name, `Lead mining complete. Found ${enrichedLeads.length} leads.`);

            return {
                success: true,
                message: `Sikeresen bányásztam ${enrichedLeads.length} leadet a(z) "${query}" keresésre.`,
                data: { leads: enrichedLeads, jobId }
            };

        } catch (error: any) {
            logError(this.name, `Lead mining failed: ${error.message}`);
            if (jobId) {
                await updateBusinessJobStatus(jobId, 'failed', JSON.stringify({ error: error.message }));
            }
            return { success: false, message: `Hiba a lead mining során: ${error.message}` };
        }
    }
}

