                if (!job || !job.results_json) {
                    return { isError: true, content: [{ type: "text", text: `Job not found or has no results: ${jobId}` }] };
                }

                const data = JSON.parse(job.results_json);
                if (!Array.isArray(data) || data.length === 0) {
                    return { isError: true, content: [{ type: "text", text: `Job results are empty or invalid.` }] };
                }

                const auth = await getGoogleAuth();
                const sheets = google.sheets({ version: 'v4', auth });

                // 2. Create Spreadsheet
                const createRes = await sheets.spreadsheets.create({
                    requestBody: {
                        properties: { title: title || `BAS Export: ${job.query} (${job.type})` }
                    }
