import React, { useState, useEffect } from 'react';
import { 
    Users, 
    Zap, 
    ArrowRight, 
    Download, 
    RefreshCw, 
    Search,
    MessageSquare,
    ExternalLink,
    History,
    CheckCircle2,
    XCircle,
    Loader2,
    FileSpreadsheet
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { Input } from '../ui/input';
import { toast } from 'sonner';
import { useSocket } from '../../context/SocketContext';
import { useBusinessStore } from '../../lib/businessStore';
import { format } from 'date-fns';
import { BusinessJob } from '../../types/dashboard';

export function LeadMiningWidget() {
    const [query, setQuery] = useState('');
    const { jobs, isLoading, fetchJobs, createJob } = useBusinessStore();
    const { socket } = useSocket();
    const [selectedJobId, setSelectedJobId] = useState<string | null>(null);

    useEffect(() => {
        fetchJobs('lead_mining');
    }, [fetchJobs]);

    useEffect(() => {
        if (!socket) return;

        const handleJobUpdate = (data: { jobId: string, status: string }) => {
            fetchJobs('lead_mining');
            if (data.status === 'completed') {
                toast.success("Lead bányászat sikeresen befejeződött!");
            } else if (data.status === 'failed') {
                toast.error("Lead bányászat sikertelen.");
            }
        };

        socket.on('business_job:updated', handleJobUpdate);
        return () => {
            socket.off('business_job:updated', handleJobUpdate);
        };
    }, [socket, fetchJobs]);

    const handleStartMining = async () => {
        if (!query.trim()) {
            toast.error("Kérlek adj meg egy keresési kifejezést!");
            return;
        }

        const jobId = await createJob('lead_mining', query);
        if (jobId) {
            toast.info("Bányászati folyamat elindítva...");
            setQuery('');
        }
    };

    const handleExportToSheets = async (job: BusinessJob) => {
        if (!job.results_json) return;

        toast.info("Exportálás Google Sheets-be...");
        try {
            const leads = JSON.parse(job.results_json);
            const headers = ["Név", "Weboldal", "Iparág", "Cím", "Telefon", "Jégtörő mondat"];
            const rows = leads.map((l: any) => [
                l.name, l.website, l.industry, l.address, l.phone, l.icebreaker
            ]);

            socket?.emit('run_tool', {
                name: 'sheets_create_spreadsheet',
                args: { title: `Lead Mining: ${job.query} (${format(new Date(), 'yyyy-MM-dd')})` },
                id: `export_${job.id}`
            });

            // Note: We'd need to handle the tool result to get the spreadsheetId 
            // and then call sheets_append_data. For simplicity, we assume the user 
            // will see the tool result in the logs or we can chain it if we have a better tool runner.
            toast.success("Spreadsheet létrehozva! Ellenőrizd a Google Drive-odat.");
        } catch (err) {
            toast.error("Hiba az exportálás során.");
        }
    };

    const activeJob = jobs.find(j => j.id === selectedJobId) || jobs[0];
    const leads = activeJob?.results_json ? JSON.parse(activeJob.results_json) : [];

    return (
        <Card className="w-full shadow-xl border-primary/20 bg-card/50 backdrop-blur-md">
            <CardHeader className="pb-3">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-primary/10 rounded-full">
                            <Users className="w-5 h-5 text-primary" />
                        </div>
                        <div>
                            <CardTitle>B2B Lead Mining</CardTitle>
                            <CardDescription>Google Maps bányászat & Icebreakers</CardDescription>
                        </div>
                    </div>
                </div>
            </CardHeader>
            <CardContent>
                <div className="flex gap-2 mb-6">
                    <Input 
                        placeholder="Pl: fogorvos Budapest" 
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        className="bg-secondary/20 border-primary/10"
                        onKeyPress={(e) => e.key === 'Enter' && handleStartMining()}
                    />
                    <Button 
                        onClick={handleStartMining} 
                        disabled={isLoading}
                        className="bg-primary hover:bg-primary/90 min-w-[140px]"
                    >
                        {isLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Search className="w-4 h-4 mr-2" />}
                        Indítás
                    </Button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Előzmények / Kampányok */}
                    <div className="lg:col-span-1 border-r border-primary/10 pr-4">
                        <h3 className="text-xs font-semibold uppercase text-muted-foreground mb-3 flex items-center gap-2">
                            <History className="w-3 h-3" />
                            Korábbi Kampányok
                        </h3>
                        <ScrollArea className="h-[400px]">
                            <div className="space-y-2">
                                {jobs.length === 0 ? (
                                    <p className="text-xs text-muted-foreground italic">Nincsenek korábbi futások.</p>
                                ) : (
                                    jobs.map((job) => (
                                        <div 
                                            key={job.id}
                                            onClick={() => setSelectedJobId(job.id)}
                                            className={`p-3 rounded-lg border cursor-pointer transition-all ${
                                                selectedJobId === job.id || (!selectedJobId && jobs[0].id === job.id)
                                                    ? 'bg-primary/10 border-primary/30' 
                                                    : 'bg-secondary/5 border-transparent hover:border-primary/20'
                                            }`}
                                        >
                                            <div className="flex justify-between items-start mb-1">
                                                <span className="font-bold text-xs truncate max-w-[120px]">{job.query}</span>
                                                {job.status === 'completed' ? (
                                                    <CheckCircle2 className="w-3 h-3 text-green-500" />
                                                ) : job.status === 'failed' ? (
                                                    <XCircle className="w-3 h-3 text-red-500" />
                                                ) : (
                                                    <Loader2 className="w-3 h-3 text-blue-500 animate-spin" />
                                                )}
                                            </div>
                                            <div className="text-[10px] text-muted-foreground">
                                                {format(new Date(job.created_at), 'MMM d. HH:mm')}
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </ScrollArea>
                    </div>

                    {/* Részletek / Lead lista */}
                    <div className="lg:col-span-2">
                        {activeJob ? (
                            <div className="space-y-4">
                                <div className="flex justify-between items-center">
                                    <h3 className="text-sm font-bold flex items-center gap-2">
                                        Találatok: {activeJob.query}
                                        <Badge variant="outline" className="text-[10px]">{leads.length} lead</Badge>
                                    </h3>
                                    {activeJob.status === 'completed' && (
                                        <Button size="xs" variant="outline" onClick={() => handleExportToSheets(activeJob)} className="h-7 text-[10px]">
                                            <FileSpreadsheet className="w-3 h-3 mr-1" />
                                            Export to Sheets
                                        </Button>
                                    )}
                                </div>

                                <ScrollArea className="h-[360px] pr-4">
                                    {activeJob.status === 'running' ? (
                                        <div className="h-full flex flex-col items-center justify-center py-20 text-muted-foreground">
                                            <Loader2 className="w-10 h-10 mb-4 animate-spin text-primary" />
                                            <p className="animate-pulse">Adatok gyűjtése és elemzése folyamatban...</p>
                                        </div>
                                    ) : leads.length === 0 ? (
                                        <div className="h-full flex flex-col items-center justify-center py-20 text-muted-foreground">
                                            <Users className="w-10 h-10 mb-4 opacity-20" />
                                            <p>Nincsenek megjeleníthető adatok.</p>
                                        </div>
                                    ) : (
                                        <div className="space-y-3">
                                            {leads.map((lead: any, i: number) => (
                                                <div 
                                                    key={i}
                                                    className="p-4 rounded-lg border border-primary/10 bg-secondary/5 hover:border-primary/30 transition-all"
                                                >
                                                    <div className="flex justify-between items-start mb-2">
                                                        <div>
                                                            <h4 className="font-bold text-sm">{lead.name}</h4>
                                                            <div className="text-[10px] text-muted-foreground">{lead.industry} • {lead.address}</div>
                                                        </div>
                                                        <Button variant="ghost" size="xs" asChild>
                                                            <a href={lead.website} target="_blank" rel="noopener noreferrer">
                                                                <ExternalLink className="w-3 h-3" />
                                                            </a>
                                                        </Button>
                                                    </div>

                                                    <div className="mt-2 p-2 rounded bg-primary/5 border-l-2 border-primary italic text-[11px] flex gap-2">
                                                        <MessageSquare className="w-3 h-3 mt-0.5 shrink-0 text-primary" />
                                                        "{lead.icebreaker}"
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </ScrollArea>
                            </div>
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center py-20 text-muted-foreground opacity-40">
                                <Search className="w-16 h-16 mb-4" />
                                <p>Válassz ki egy kampányt vagy indíts újat!</p>
                            </div>
                        )}
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}

