  /**
   * Handle invoice processing and OCR extraction
   */
  private async handleProcessInvoice(context: AgentContext): Promise<AgentResult> {
    const filePath = (context.filePath || (context as any).context?.filePath) as string;

    if (!filePath) {
      return { success: false, message: "Hiányzó fájl elérési út a feldolgozáshoz.", data: null };
    }

    logInfo(this.name, `Processing invoice file with Gemini Vision: ${filePath}`);

    try {
        // 1. Call Python OCR worker (Gemini 2.0 Flash)
        const pythonCode = `
from myai.refiners.invoice_parser import process_invoice_file
import asyncio
import json

async def run():
    result = await process_invoice_file("${filePath.replace(/\\/g, '/')}")
    print(json.dumps(result, default=str))

asyncio.run(run())
        `;

        const output = await globalPythonShell.run(pythonCode);
        const invoiceData = JSON.parse(output);

        if (invoiceData.error) {
            throw new Error(invoiceData.error);
        }

        // 2. Duplicate Detection
        const isDuplicate = await invoiceStore.isDuplicate(invoiceData.invoice_number);

        if (isDuplicate) {
            logInfo(this.name, `Duplicate invoice ignored: ${invoiceData.invoice_number}`);
            return {
                success: true,
                message: `A számla (${invoiceData.invoice_number}) már létezik a rendszerben.`,
                data: { isDuplicate: true, invoiceData }
            };
        }

        // 3. Save to LanceDB
        await invoiceStore.addInvoice(invoiceData);

        return {
            success: true,
            message: `Számla (${invoiceData.invoice_number}) sikeresen feldolgozva (Gemini Vision) és mentve.`,
            data: { isDuplicate: false, invoiceData }
        };

    } catch (error: any) {
        logError(this.name, `OCR Processing failed: ${error.message}`);
        return { success: false, message: `Hiba a számla feldolgozása során: ${error.message}`, data: null };
    }
  }

