import { useMemo, useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { toast } from "sonner";
import { 
    RefreshCcw, 
    FileSpreadsheet, 
    Mail, 
    Search, 
    FileCheck, 
    CheckCircle2, 
    History, 
    Loader2, 
    XCircle 
} from "lucide-react";
import { useSocket } from "../../context/SocketContext";
import { useBusinessStore } from "../../lib/businessStore";
import { format } from "date-fns";
import { ScrollArea } from "../ui/scroll-area";

export function InvoiceSyncWidget() {
  const { jobs, isLoading, fetchJobs, createJob } = useBusinessStore();
  const { socket } = useSocket();
  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);

  const invoiceJobs = useMemo(() => 
    jobs.filter(j => j.type === 'invoice_sync'), 
  [jobs]);

  useEffect(() => {
    fetchJobs('invoice_sync');
  }, [fetchJobs]);

  useEffect(() => {
    if (!socket) return;

    const handleJobUpdate = (data: { jobId: string, status: string }) => {
      fetchJobs('invoice_sync');
      if (data.status === 'completed') {
        toast.success("Számla szinkronizálás sikeresen befejeződött!");
      } else if (data.status === 'failed') {
        toast.error("Számla szinkronizálás sikertelen.");
      }
    };

    socket.on('business_job:updated', handleJobUpdate);
    return () => {
      socket.off('business_job:updated', handleJobUpdate);
    };
  }, [socket, fetchJobs]);

  const handleFullAutomation = async () => {
    toast.info("Számla szinkronizálás indítása...");
    const jobId = await createJob('invoice_sync', 'Sync latest invoices from Gmail');
    if (jobId) {
      setSelectedJobId(jobId);
    }
  };

  const activeJob = jobs.find(j => j.id === selectedJobId) || invoiceJobs[0];
  const results = activeJob?.results_json ? JSON.parse(activeJob.results_json) : null;

  return (
    <Card className="glass-card border-white/5 bg-black/40 backdrop-blur-xl h-full flex flex-col">
      <CardHeader className="p-4 border-b border-white/5">
        <CardTitle className="flex items-center justify-between text-xs font-bold tracking-widest uppercase text-white">
          <span className="flex items-center gap-2">
            <FileSpreadsheet size={16} className="text-emerald-400" />
            Invoice Automation (MT2)
          </span>
          {activeJob && (
            <Badge variant={activeJob.status === "completed" ? "default" : activeJob.status === "failed" ? "destructive" : "secondary"}>
              {activeJob.status.toUpperCase()}
            </Badge>
          )}
        </CardTitle>
      </CardHeader>
      <CardContent className="p-4 flex-1 flex flex-col gap-6 overflow-hidden">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1 min-h-0">

          {/* Előzmények */}
          <div className="md:col-span-1 border-r border-white/5 pr-4 flex flex-col gap-3">
            <h3 className="text-[10px] font-mono text-zinc-500 uppercase flex items-center gap-2">
              <History size={12} />
              Szinkron Előzmények
            </h3>
            <ScrollArea className="flex-1">
              <div className="space-y-2">
                {invoiceJobs.length === 0 ? (
                  <p className="text-[10px] text-zinc-600 italic">Nincsenek korábbi futások.</p>
                ) : (
                  invoiceJobs.map((job) => (
                    <div 
                      key={job.id}
                      onClick={() => setSelectedJobId(job.id)}
                      className={`p-3 rounded-lg border cursor-pointer transition-all ${
                        selectedJobId === job.id || (!selectedJobId && invoiceJobs[0].id === job.id)
                          ? 'bg-emerald-500/10 border-emerald-500/30' 
                          : 'bg-white/5 border-transparent hover:border-white/10'
                      }`}
                    >
                      <div className="flex justify-between items-center mb-1">
                        <span className="text-[10px] font-bold text-zinc-300">
                          {format(new Date(job.created_at), 'MMM d. HH:mm')}
                        </span>
                        {job.status === 'completed' ? (
                          <CheckCircle2 size={12} className="text-emerald-500" />
                        ) : job.status === 'failed' ? (
                          <XCircle size={12} className="text-red-500" />
                        ) : (
                          <Loader2 size={12} className="text-blue-500 animate-spin" />
                        )}
                      </div>
                      <div className="text-[9px] text-zinc-500 truncate">{job.query}</div>
                    </div>
                  ))
                )}
              </div>
            </ScrollArea>
          </div>

          {/* Részletek / Eredmények */}
          <div className="md:col-span-2 flex flex-col gap-4">
            {activeJob ? (
              <>
                <div className="grid grid-cols-3 gap-2">
                  <div className="p-3 rounded-lg bg-white/5 border border-white/5 flex flex-col items-center gap-1">
                    <Mail size={16} className={activeJob.status === "running" ? "text-blue-400 animate-pulse" : "text-emerald-400"} />
                    <span className="text-[9px] uppercase text-zinc-500">Gmail</span>
                  </div>
                  <div className="p-3 rounded-lg bg-white/5 border border-white/5 flex flex-col items-center gap-1">
                    <Search size={16} className={activeJob.status === "running" ? "text-purple-400 animate-pulse" : "text-emerald-400"} />
                    <span className="text-[9px] uppercase text-zinc-500">Vision OCR</span>
                  </div>
                  <div className="p-3 rounded-lg bg-white/5 border border-white/5 flex flex-col items-center gap-1">
                    <FileCheck size={16} className={activeJob.status === "running" ? "text-emerald-400 animate-pulse" : "text-emerald-400"} />
                    <span className="text-[9px] uppercase text-zinc-500">Sheets</span>
                  </div>
                </div>

                <div className="flex-1 min-h-0 bg-white/5 rounded-xl border border-white/5 p-4">
                  <h4 className="text-[10px] font-mono text-zinc-500 uppercase mb-3">Eredmények</h4>
                  <ScrollArea className="h-full">
                    {activeJob.status === 'running' ? (
                      <div className="h-full flex flex-col items-center justify-center py-10 text-zinc-500">
                        <Loader2 size={32} className="mb-4 animate-spin text-emerald-500" />
                        <p className="text-xs animate-pulse">Számlák letöltése és OCR feldolgozása...</p>
                      </div>
                    ) : results ? (
                      <div className="space-y-3">
                        <div className="p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/10">
                          <p className="text-xs font-bold text-emerald-200">Feldolgozás kész</p>
                          <p className="text-[10px] text-zinc-400 mt-1">
                            A kinyert adatok mentve a LanceDB-be és exportálva a Google Sheets táblázatba.
                          </p>
                        </div>
                        {/* Itt megjeleníthetnénk a kinyert számlák listáját ha a results_json-ban az van */}
                        <pre className="text-[10px] font-mono text-zinc-500 bg-black/20 p-2 rounded overflow-auto max-h-[200px]">
                          {JSON.stringify(results, null, 2)}
                        </pre>
                      </div>
                    ) : (
                      <div className="h-full flex flex-col items-center justify-center py-10 text-zinc-600">
                        <p className="text-xs">Nincsenek adatok.</p>
                      </div>
                    )}
                  </ScrollArea>
                </div>
              </>
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-zinc-600 opacity-40">
                <Mail size={48} className="mb-4" />
                <p className="text-sm">Válassz ki egy korábbi szinkront vagy indíts újat!</p>
              </div>
            )}
          </div>
        </div>

        <Button 
          onClick={handleFullAutomation} 
          disabled={activeJob?.status === 'running'}
          className="w-full gap-2 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 border border-emerald-500/20 transition-all"
        >
          {activeJob?.status === 'running' ? <Loader2 size={14} className="animate-spin" /> : <RefreshCcw size={14} />}
          Új Számla Szinkronizálás Indítása
        </Button>
      </CardContent>
    </Card>
  );
}

