    if (jobId) {
        await updateBusinessJobStatus(jobId, 'running');
        socketService.emit('business_job:updated', { jobId, status: 'running' });
    }

    try {
      // MASTER TRACK 2: Full Automation Orchestrator
      if (task.toLowerCase().includes('szinkronizáld a számlákat') || (context as any).taskType === 'full_sync') {
        return await this.handleFullSync(context);
      }

      // MASTER TRACK 2: Task 1 - Gmail PDF Download
      if (task.toLowerCase().includes('download pdf invoice from gmail') || (context as any).taskType === 'download_invoice') {
