import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { logInfo, logError } from '../utils/logger.js';
import { getWorkspaceClient } from '../tools/unifiedWorkspace.js';
import { invoiceStore } from '../utils/lancedb_client.js';
import { updateBusinessJobStatus } from '../utils/db.js';
import { socketService } from '../server/SocketService.js';
import { globalPythonShell } from '../utils/pythonShell.js';
import * as fs from 'fs/promises';
import * as path from 'path';

/**
 * Invoice Data Structure
 */
interface InvoiceData {
  invoice_number: string;
  vendor_name: string;
  amount: number;
  currency: string;
  invoice_date: string;
  due_date?: string;
  line_items: Array<{
    description: string;
    quantity: number;
    unit_price: number;
    total: number;
  }>;
  confidence: number;
}

/**
 * Legacy Invoice Data Structure (for internal history)
 */
interface LegacyInvoiceData {
  invoiceNumber: string;
  vendor: string;
  amount: number;
  currency: string;
  date: Date;
  dueDate?: Date;
  lineItems: Array<{
    description: string;
    quantity: number;
    unitPrice: number;
    total: number;
  }>;
  confidence: number;
}

/**
 * Price Anomaly
 */
interface PriceAnomaly {
  vendorId: string;
  vendorName: string;
  productCategory: string;
  historicalAvgPrice: number;
  currentPrice: number;
  percentageChange: number;
  anomalyScore: number;
  severity: 'low' | 'medium' | 'high' | 'critical';
  reasoning: string;
}

export class FinanceGuardian extends BaseAgent {
  name = 'FinanceGuardian';
  role = 'Financial Monitoring & Anomaly Detection';
  description = 'Pénzügyi Őrszem - Processes invoices, detects anomalies, generates financial reports';
  capabilities = ['invoice_processing', 'ocr_extraction', 'anomaly_detection', 'trend_analysis', 'cost_optimization'];

  private invoiceHistory: Map<string, any[]> = new Map();
  private priceBaselineByVendor: Map<string, { avgPrice: number; stdDev: number }> = new Map();

  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = context.task || '';
    const jobId = (context as any).jobId;
    const startTime = Date.now();

    if (jobId) {
        await updateBusinessJobStatus(jobId, 'running');
        socketService.emit('business_job:updated', { jobId, status: 'running' });
    }

    try {
      // MASTER TRACK 2: Full Automation Orchestrator
      if (task.toLowerCase().includes('szinkronizáld a számlákat') || (context as any).taskType === 'full_sync') {
        return await this.handleFullSync(context);
      }

      // MASTER TRACK 2: Task 1 - Gmail PDF Download
      if (task.toLowerCase().includes('download pdf invoice from gmail') || (context as any).taskType === 'download_invoice') {
        return await this.handleGmailDownload(context);
      }

      // Default logic: Mock processing for other tasks
      const invoices = await this.extractInvoicesFromPDFs();
      return {
        success: true,
        message: `Processed ${invoices.length} mock invoices.`,
        data: { count: invoices.length },
        metadata: { processingTimeMs: Date.now() - startTime }
      };
    } catch (e: any) {
      logError(this.name, `Task failed: ${e.message}`);
      if (jobId) {
          await updateBusinessJobStatus(jobId, 'failed', JSON.stringify({ error: e.message }));
          socketService.emit('business_job:updated', { jobId, status: 'failed' });
      }
      return { success: false, message: `Task failed: ${e.message}` };
    }
  }

  private async handleFullSync(context: AgentContext): Promise<AgentResult> {
    const jobId = (context as any).jobId;
    logInfo(this.name, `Starting full invoice sync orchestrator (Job: ${jobId})`);

    try {
        const downloadResult = await this.handleGmailDownload(context);
        const files = (downloadResult.data as any)?.downloadedFiles || [];

        if (files.length === 0) {
            if (jobId) {
                await updateBusinessJobStatus(jobId, 'completed', JSON.stringify({ message: "No new invoices found", count: 0 }));
                socketService.emit('business_job:updated', { jobId, status: 'completed' });
            }
            return downloadResult;
        }

        const processedResults = [];
        for (const file of files) {
            const processResult = await this.handleProcessInvoice({ ...context, filePath: file });
            processedResults.push({
                file: path.basename(file),
                success: processResult.success,
                message: processResult.message,
                data: processResult.data
            });

            const resData = processResult.data as any;
            if (processResult.success && resData?.invoiceData && !resData.isDuplicate) {
                await this.handleSheetsExport({ 
                    ...context, 
                    invoiceData: resData.invoiceData 
                });
            }
        }

        if (jobId) {
            await updateBusinessJobStatus(jobId, 'completed', JSON.stringify(processedResults));
            socketService.emit('business_job:updated', { jobId, status: 'completed' });
        }

        return {
            success: true,
            message: `Sikeresen feldolgoztam ${files.length} db számlát.`,
            data: processedResults
        };
    } catch (error: any) {
        logError(this.name, `Full sync failed: ${error.message}`);
        return { success: false, message: `Hiba a teljes szinkronizálás során: ${error.message}` };
    }
  }

  private async handleGmailDownload(context: AgentContext): Promise<AgentResult> {
    const query = (context.query as string) || 'has:attachment filename:pdf "számla" OR "invoice"';
    const workspace = await getWorkspaceClient();
    const messages = await workspace.searchEmails(query, 5);

    if (messages.length === 0) {
      return { success: true, message: "Nincs új számla.", data: { downloadedFiles: [] } };
    }

    const downloadedFiles: string[] = [];
    const tempDir = path.join(process.cwd(), '_br_temp', 'invoices');
    await fs.mkdir(tempDir, { recursive: true });

    for (const msg of messages) {
      const attachments = await workspace.getEmailAttachments(msg.id!);
      for (const att of attachments) {
        if (att.filename.toLowerCase().endsWith('.pdf')) {
          const localPath = path.join(tempDir, `${msg.id}_${att.filename}`);
          await fs.writeFile(localPath, att.data);
          downloadedFiles.push(localPath);
        }
      }
    }

    return { success: true, message: `${downloadedFiles.length} db számla letöltve.`, data: { downloadedFiles } };
  }

  private async handleProcessInvoice(context: AgentContext): Promise<AgentResult> {
    const filePath = (context.filePath || (context as any).context?.filePath) as string;
    if (!filePath) return { success: false, message: "Nincs fájl.", data: null };

    try {
        const cleanPath = filePath.split('\\').join('/');
        const pythonCode = `
from myai.refiners.invoice_parser import process_invoice_file
import asyncio
import json

async def run():
    result = await process_invoice_file("${cleanPath}")
    print(json.dumps(result, default=str))

asyncio.run(run())
`;
        const output = await globalPythonShell.run(pythonCode);
        const invoiceData = JSON.parse(output);

        if (invoiceData.error) throw new Error(invoiceData.error);

        const isDuplicate = await invoiceStore.isDuplicate(invoiceData.invoice_number);
        if (isDuplicate) {
            return { success: true, message: "Duplikátum.", data: { isDuplicate: true, invoiceData } };
        }

        await invoiceStore.addInvoice(invoiceData);
        return { success: true, message: "Siker.", data: { isDuplicate: false, invoiceData } };
    } catch (error: any) {
        return { success: false, message: error.message, data: null };
    }
  }

  private async handleSheetsExport(context: AgentContext): Promise<AgentResult> {
    const invoiceData = (context.invoiceData || context.context) as any;
    const spreadsheetId = (context.spreadsheetId as string) || process.env.INVOICE_SPREADSHEET_ID;

    if (!invoiceData || !spreadsheetId) return { success: false, message: "Hiányzó adatok.", data: null };

    const workspace = await getWorkspaceClient();
    const row = [
      invoiceData.invoice_number,
      invoiceData.vendor_name,
      invoiceData.amount,
      invoiceData.currency || 'HUF',
      invoiceData.invoice_date || '',
      invoiceData.due_date || '',
      new Date().toISOString()
    ];

    await workspace.performSheetOperation({
      operation: 'append',
      spreadsheetId,
      range: 'Sheet1!A:G',
      values: [row]
    });

    return { success: true, message: "Exportálva.", data: { spreadsheetId } };
  }

  private async extractInvoicesFromPDFs(): Promise<LegacyInvoiceData[]> {
    return []; // Mock simplified
  }

  private async storeInvoiceHistory(invoices: LegacyInvoiceData[]): Promise<void> {}
  private calculateVendorBaselines(): void {}
  private detectAnomalies(invoices: LegacyInvoiceData[]): PriceAnomaly[] { return []; }
}

export const createFinanceGuardian = (): FinanceGuardian => new FinanceGuardian();
export default FinanceGuardian;

