import json
import sys
from typing import Dict, Any, List

def evaluate_product(item: Dict[str, Any]) -> Dict[str, Any]:
    """
    Evaluates a single product item and gives it a potential score.
    """
    # Clean price
    price_str = str(item.get('price', '0'))
    price = 0
    try:
        price = float(''.join(filter(lambda x: x.isdigit() or x == '.', price_str.replace(',', '.'))))
    except:
        price = 0

    # Mock logic for valuation
    # In reality, this would query historical data in LanceDB
    market_avg = price * 1.2 # Assume it's 20% higher normally

    potential_score = 0.5
    recommendation = "WATCH"

    if price > 0:
        if price < market_avg * 0.8:
            potential_score = 0.85
            recommendation = "BUY"
        elif price > market_avg * 1.1:
            potential_score = 0.2
            recommendation = "OVERPRICED"

    return {
        "price_numeric": price,
        "market_average": market_avg,
        "potential_score": potential_score,
        "recommendation": recommendation
    }

def main():
    if len(sys.argv) < 2:
        print(json.dumps({}))
        return

    try:
        data = json.loads(sys.argv[1])
        if isinstance(data, list):
            results = [ {**item, **evaluate_product(item)} for item in data ]
        else:
            results = {**data, **evaluate_product(data)}

        print(json.dumps(results, default=str))
    except Exception as e:
        print(json.dumps({"error": str(e)}))

if __name__ == "__main__":
    main()

