import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { AgentResponse } from './types.js';
import { logInfo, logError, logWarn, setAgentStatus } from '../utils/logger.js';
import { agentManager } from './AgentManager.js';
import { runPythonWorker } from '../utils/pythonShell.js';
import { lanceDBClient } from '../utils/lancedb_client.js';
import { getWorkspaceClient } from '../tools/unifiedWorkspace.js';
import { updateBusinessJobStatus } from '../utils/db.js';
import { socketService } from '../server/SocketService.js';
import type { MarketIntelData, MarketIntelRecord } from '../types/enterprise.js';

interface PricePoint {
  productName: string;
  competitor: string;
  price: number;
  currency: string;
  sourceUrl: string;
  scrapedAt: string;
}

interface PriceAlert {
  productName: string;
  competitor: string;
  oldPrice: number;
  newPrice: number;
  priceChangePercent: number;
  timestamp: string;
  severity: 'critical' | 'warning' | 'info';
}

export class MarketIntelAgent extends BaseAgent {
  name = 'MarketIntel';
  role = 'Competitor Price Monitoring & Market Analysis';
  description = 'Automated competitor website scraping, price tracking, and trend analysis with LanceDB storage';
  capabilities = [
    'competitor_scraping',
    'price_tracking',
    'trend_analysis',
    'alert_system',
    'lancedb_storage',
    'chart_generation'
  ];

  private readonly PRICE_DROP_THRESHOLD = 10;
  private priceHistory: Map<string, PricePoint[]> = new Map();

  private isTestMode(): boolean {
    return process.env.NODE_ENV === 'test' || process.env.VITEST === 'true';
  }

  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = (context.task || '').trim();
    const jobId = (context as any).jobId;
    if (!task) return { success: false, message: 'Üres feladat leírás' };

    if (jobId) {
        await updateBusinessJobStatus(jobId, 'running');
        socketService.emit('business_job:updated', { jobId, status: 'running' });
    }

    setAgentStatus(this.name, 'working', `Piaci hírszerzés: ${task.substring(0, 50)}...`);

    try {
        if (task.toLowerCase().includes('monitor product prices') || (context as any).taskType === 'monitor_market') {
            const result = await this.handleMarketMonitoring(context);
            if (jobId) {
                const status = result.success ? 'completed' : 'failed';
                await updateBusinessJobStatus(jobId, status, JSON.stringify(result.data));
                socketService.emit('business_job:updated', { jobId, status });
            }
            return result;
        }

        if (task.toLowerCase().includes('machine hunt') || (context as any).taskType === 'machine_hunt') {
            const result = await this.handleMachineHunt(context);
            if (jobId) {
                const status = result.success ? 'completed' : 'failed';
                await updateBusinessJobStatus(jobId, status, JSON.stringify(result.data));
                socketService.emit('business_job:updated', { jobId, status });
            }
            return result;
        }

        return { success: true, message: "General market intel processing complete." };
    } catch (error: any) {
        logError(this.name, `Market Intel failed: ${error.message}`);
        if (jobId) {
            await updateBusinessJobStatus(jobId, 'failed', JSON.stringify({ error: error.message }));
            socketService.emit('business_job:updated', { jobId, status: 'failed' });
        }
        return { success: false, message: error.message };
    } finally {
        setAgentStatus(this.name, 'idle');
    }
  }

  private async handleMarketMonitoring(context: AgentContext): Promise<AgentResult> {
    const { url, selectors, productCategory } = (context.context || context) as any;
    if (!url || !selectors) return { success: false, message: "URL és selectorok kötelezőek.", data: null };

    try {
      const scrapedData = await runPythonWorker('market_scraper.py', { url, selectors });
      if (!scrapedData || (Array.isArray(scrapedData) && scrapedData.length === 0)) {
        return { success: false, message: "Nincs adat.", data: null };
      }

      const valuationResult = await runPythonWorker('product_valuation.py', scrapedData);
      const marketData = {
        results: valuationResult,
        category: productCategory || "general",
        timestamp: new Date().toISOString(),
        url: url
      };

      await lanceDBClient.addData('market_intel_data', marketData);
      return { success: true, message: "Sikeres figyelés.", data: marketData };
    } catch (e: any) {
      return { success: false, message: e.message, data: null };
    }
  }

  private async handleMachineHunt(context: AgentContext): Promise<AgentResult> {
    const query = context.query || context.task || "CNC machine";
    try {
      const machines = await runPythonWorker('machine_scraper.py', [query, '5']);
      if (!machines || machines.length === 0) return { success: false, message: "Nincs találat." };

      const opportunities = [];
      for (const machine of machines) {
        const valuation = await runPythonWorker('product_valuation.py', { ...machine, market_average: machine.price * 1.3 });
        if (valuation.recommendation === 'BUY' || valuation.potential_score > 0.7) {
          opportunities.push({ ...machine, ...valuation });
        }
      }

      await lanceDBClient.addData('machine_opportunities', opportunities);
      return { success: true, message: `Gépvadászat kész: ${opportunities.length} lehetőség.`, data: opportunities };
    } catch (e: any) {
      return { success: false, message: e.message };
    }
  }
}

export const createMarketIntelAgent = (): MarketIntelAgent => new MarketIntelAgent();
export default MarketIntelAgent;

