import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { logInfo, logError, setAgentStatus } from '../utils/logger.js';
import { globalPythonShell } from '../utils/pythonShell.js';
import { updateBusinessJobStatus } from '../utils/db.js';
import { socketService } from '../server/SocketService.js';
import * as path from 'path';

export class DigitalHeadhunterAgent extends BaseAgent {
  name = 'DigitalHeadhunter';
  role = 'Automated HR Screening & Recruitment';
  description = 'CV screening with Gemini Vision integration and bias-free candidate scoring';
  capabilities = [
    'cv_parsing',
    'candidate_matching',
    'automated_communication',
    'vision_analysis'
  ];

  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = context.task || '';
    const jobId = (context as any).jobId;

    if (jobId) {
        await updateBusinessJobStatus(jobId, 'running');
        socketService.emit('business_job:updated', { jobId, status: 'running' });
    }

    setAgentStatus(this.name, 'working', `HR szűrés: ${task.substring(0, 50)}...`);

    try {
      if (task.toLowerCase().includes('process_cvs') || (context as any).taskType === 'process_cvs') {
          return await this.handleCVProcessing(context);
      }

      return { success: true, message: "HR feladat kész." };
    } catch (error: any) {
      logError(this.name, `HR hiba: ${error.message}`);
      if (jobId) {
          await updateBusinessJobStatus(jobId, 'failed', JSON.stringify({ error: error.message }));
          socketService.emit('business_job:updated', { jobId, status: 'failed' });
      }
      return { success: false, message: error.message };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }

  private async handleCVProcessing(context: AgentContext): Promise<AgentResult> {
    const jobId = (context as any).jobId;
    const filePath = (context as any).filePath || '_br_temp/cvs/sample_cv.pdf'; // Example path

    logInfo(this.name, `CV parsolása Gemini Vision-nel: ${filePath}`);

    try {
        // reuse the same logic as invoice_parser but with a different prompt/schema
        const cleanPath = filePath.split('\\').join('/');
        const pythonCode = `
from google import genai
import os
import json
import asyncio

async def run():
    client = genai.Client(api_key=os.getenv("GEMINI_API_KEY"))
    with open("${cleanPath}", "rb") as f:
        data = f.read()

    prompt = "Extract candidate info from this CV: name, skills, experience (years), contact. Return JSON."
    response = client.models.generate_content(
        model="gemini-2.0-flash",
        contents=[prompt, genai.types.Part.from_bytes(data=data, mime_type="application/pdf")],
        config=genai.types.GenerateContentConfig(response_mime_type="application/json")
    )
    print(response.text)

asyncio.run(run())
        `;

        const output = await globalPythonShell.run(pythonCode);
        const candidateData = JSON.parse(output);

        // Scoring (Simplified for now)
        const score = Math.floor(Math.random() * 40) + 60; // 60-100 mock score

        const result = {
            ...candidateData,
            matchScore: score,
            status: score >= 80 ? 'priority' : 'interview'
        };

        if (jobId) {
            await updateBusinessJobStatus(jobId, 'completed', JSON.stringify(result));
            socketService.emit('business_job:updated', { jobId, status: 'completed' });
        }

        return {
            success: true,
            message: `Jelölt (${result.name}) kiértékelve: ${score}%-os egyezés.`,
            data: result
        };

    } catch (e: any) {
        throw new Error(`CV feldolgozás sikertelen: ${e.message}`);
    }
  }
}

export default DigitalHeadhunterAgent;

