      },
      {
        grantId: 'GRANT-EU-002',
        grantName: 'Horizon Europe - SME Instrument',
        funder: 'European Commission',
        deadline: new Date(Date.now() + 120 * 24 * 60 * 60 * 1000), // 120 days from now
