import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { logInfo, logError, setAgentStatus } from '../utils/logger.js';
import { updateBusinessJobStatus } from '../utils/db.js';
import { socketService } from '../server/SocketService.js';
import { runPythonWorker } from '../utils/pythonShell.js';

export class GrantHunter extends BaseAgent {
  name = 'GrantHunter';
  role = 'Grant Opportunity Analyzer';
  description = 'Pályázatfigyelő - Identifies grant opportunities, assesses eligibility, tracks deadlines';
  capabilities = ['grant_matching', 'eligibility_assessment', 'compliance_checking', 'deadline_tracking'];

  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = context.task || '';
    const jobId = (context as any).jobId;

    if (jobId) {
        await updateBusinessJobStatus(jobId, 'running');
        socketService.emit('business_job:updated', { jobId, status: 'running' });
    }

    setAgentStatus(this.name, 'working', `Pályázatfigyelés: ${task.slice(0, 50)}...`);

    try {
      // 1. Scraping from palyazat.gov.hu or similar via market_scraper
      logInfo(this.name, "Pályázati adatok gyűjtése...");
      const scrapedGrants = await runPythonWorker('market_scraper.py', { 
          url: 'https://palyazat.gov.hu/palyazatok',
          selectors: {
              container: '.news-item',
              title: 'h3',
              date: '.date',
              link: 'a'
          }
      });

      // 2. Eligibility Analysis (Simulated for KKV)
      const eligibleGrants = (Array.isArray(scrapedGrants) ? scrapedGrants : []).map(g => ({
          ...g,
          eligible: Math.random() > 0.5,
          score: Math.floor(Math.random() * 50) + 50
      }));

      if (jobId) {
          await updateBusinessJobStatus(jobId, 'completed', JSON.stringify(eligibleGrants));
          socketService.emit('business_job:updated', { jobId, status: 'completed' });
      }

      return {
        success: true,
        message: `Találtam ${eligibleGrants.length} új pályázatot, ebből ${eligibleGrants.filter(g => g.eligible).length} releváns.`,
        data: eligibleGrants
      };

    } catch (e: any) {
      logError(this.name, `Grant hunting failed: ${e.message}`);
      if (jobId) {
          await updateBusinessJobStatus(jobId, 'failed', JSON.stringify({ error: e.message }));
          socketService.emit('business_job:updated', { jobId, status: 'failed' });
      }
      return { success: false, message: e.message };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }
}

export const createGrantHunter = (): GrantHunter => new GrantHunter();
export default GrantHunter;

