import { IAgent, AgentResponse } from './types.js';
import { logInfo, logError, logWarn, setAgentStatus } from '../utils/logger.js';
import { generateResponse } from '../core/llm_client.js';
import { updateBusinessJobStatus } from '../utils/db.js';
import { socketService } from '../server/SocketService.js';

/**
 * TRIZPrinciple - TRIZ (Theory of Inventive Problem Solving) alapelvek
 */
export interface TRIZPrinciple {
  id: number;
  name: string;
  description: string;
}

/**
 * AbstractProblem - Iparág-semleges problémaleírás
 */
export interface AbstractProblem {
  originalProblem: string;
  originalIndustry: string;
  abstractChallenge: string;
  trizPrinciples: TRIZPrinciple[];
  searchKeywords: string[];
}

/**
 * InnovationSolution - Cross-industry megoldás
 */
export interface InnovationSolution {
  sourceIndustry: string;
  solutionDescription: string;
  applicability: string;
  confidence: number;
  source?: string;
}

/**
 * InnovationBridgeReport - Teljes innováció transfer riport
 */
export interface InnovationBridgeReport {
  problem: AbstractProblem;
  solutions: InnovationSolution[];
  reportDate: string;
  markdown: string;
}

/**
 * InnovationBridgeAgent - Cross-Industry Knowledge Transfer Agent
 */
export class InnovationBridgeAgent implements IAgent {
  name = 'InnovationBridge';
  role = 'Cross-Industry Innovation Transfer Specialist';
  description = 'TRIZ-alapú cross-industry knowledge transfer: iparági problémák megoldása más iparágakból származó innovációkkal';
  capabilities = [
    'problem_abstraction',
    'triz_analysis',
    'cross_industry_search',
    'analogy_matching',
    'innovation_reporting'
  ];

  private readonly trizPrinciples: TRIZPrinciple[] = [
    { id: 1, name: 'Segmentation', description: 'Divide an object into independent parts' },
    { id: 2, name: 'Taking out', description: 'Separate interfering part or property from object' },
    { id: 10, name: 'Preliminary action', description: 'Perform required changes in advance' },
    { id: 15, name: 'Dynamicity', description: 'Make object adaptive, flexible' },
    { id: 17, name: 'Another dimension', description: 'Move to multi-level or 3D arrangement' },
    { id: 28, name: 'Mechanics substitution', description: 'Replace mechanical system with optical, acoustic, etc.' },
    { id: 35, name: 'Parameter changes', description: 'Change physical/chemical parameters' },
  ];

  async execute(task: string, context?: any): Promise<AgentResponse> {
    const jobId = context?.jobId;
    const problem = context?.problem || task;
    const industry = context?.industry || 'General Business';

    if (jobId) {
        await updateBusinessJobStatus(jobId, 'running');
        socketService.emit('business_job:updated', { jobId, status: 'running' });
    }

    setAgentStatus(this.name, 'working', `Innovációs híd: ${problem.slice(0, 50)}...`);

    try {
      logInfo(this.name, `Keresztiparágú megoldás keresése: ${problem}`);

      // 1. Probléma absztrahálása (TRIZ)
      const abstractProblem = await this.abstractProblem(problem, industry);

      if (jobId) {
          socketService.emit('system:log', { 
              message: `Probléma absztrahálva: ${abstractProblem.abstractChallenge}`, 
              type: 'info', 
              source: this.name 
          });
      }

      // 2. Analógia keresése más iparágakban
      const solutions = await this.findCrossIndustrySolutions(abstractProblem, industry);

      // 3. Jelentés generálása
      const markdown = this.generateReport(abstractProblem, solutions);

      const report: InnovationBridgeReport = {
        problem: abstractProblem,
        solutions,
        reportDate: new Date().toISOString(),
        markdown,
      };

      if (jobId) {
          await updateBusinessJobStatus(jobId, 'completed', JSON.stringify(report));
          socketService.emit('business_job:updated', { jobId, status: 'completed' });
      }

      return {
        status: 'success',
        message: `Találtam ${solutions.length} innovatív analógiát más iparágakból.`, 
        data: report,
      };

    } catch (error: any) {
      logError(this.name, `Innovation Bridge hiba: ${error.message}`);
      if (jobId) {
          await updateBusinessJobStatus(jobId, 'failed', JSON.stringify({ error: error.message }));
          socketService.emit('business_job:updated', { jobId, status: 'failed' });
      }
      return { status: 'error', error: error.message };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }

  private async abstractProblem(problem: string, industry: string): Promise<AbstractProblem> {
    const prompt = `Te egy TRIZ (Theory of Inventive Problem Solving) szakértő vagy.
    Alakítsd át ezt a problémát egy iparág-semleges absztrakt kihívássá: "${problem}" (Iparág: ${industry}).

    Adj vissza egy JSON-t:
    {
      "abstractChallenge": "Az elvont kihívás leírása",
      "trizPrinciples": [1, 10, 15],
      "searchKeywords": ["kulcsszó1", "kulcsszó2"]
    }`;

    const response = await generateResponse(prompt, 'gemini', 'gemini-2.0-flash');
    const jsonMatch = response.match(/\{[\s\S]*\}/);
    const parsed = JSON.parse(jsonMatch![0]);

    return {
      originalProblem: problem,
      originalIndustry: industry,
      abstractChallenge: parsed.abstractChallenge,
      trizPrinciples: parsed.trizPrinciples.map((id: number) => 
        this.trizPrinciples.find(p => p.id === id) || { id, name: 'Ismeretlen', description: '' }
      ),
      searchKeywords: parsed.searchKeywords
    };
  }

  private async findCrossIndustrySolutions(abstract: AbstractProblem, industry: string): Promise<InnovationSolution[]> {
    const prompt = `Te egy innovációs tanácsadó vagy. 
    Az elvont kihívás: "${abstract.abstractChallenge}"
    Alkalmazható TRIZ elvek: ${abstract.trizPrinciples.map(p => p.name).join(', ')}

    Keress 3 darab konkrét példát a VILÁGBÓL (NASA, autóipar, természet, sport, stb.), ahol egy hasonló absztrakt problémát sikeresen megoldottak. A forrás iparág NE legyen a(z) ${industry}.

    Adj vissza egy JSON tömböt:
    [
      {
        "sourceIndustry": "Iparág neve",
        "solutionDescription": "Hogyan oldották meg?",
        "applicability": "Hogyan alkalmazható ez a felhasználó eredeti problémájára?",
        "confidence": 95
      }
    ]`;

    const response = await generateResponse(prompt, 'gemini', 'gemini-2.0-flash');
    const jsonMatch = response.match(/\([\[\s\S]*\])/);
    return JSON.parse(jsonMatch![0]);
  }

  private generateReport(problem: AbstractProblem, solutions: InnovationSolution[]): string {
    let md = `# 🌉 Innovation Bridge - Stratégiai Jelentés\n\n`;
    md += `## 📋 Eredeti Probléma\n> ${problem.originalProblem}\n\n`;
    md += `## 🎯 Absztrakt Kihívás\n> ${problem.abstractChallenge}\n\n`;
    md += `## 💡 Keresztiparágú Megoldások\n\n`;

    solutions.forEach((sol, i) => {
      md += `### ${i+1}. ${sol.sourceIndustry}\n`;
      md += `**Megoldás:** ${sol.solutionDescription}\n\n`;
      md += `**Alkalmazás nálad:** ${sol.applicability}\n\n---\n`;
    });

    return md;
  }
}

export default InnovationBridgeAgent;

