import React, { useState, useEffect, useMemo } from 'react';
import { 
    Lightbulb, 
    Zap, 
    ArrowRight, 
    History,
    CheckCircle2,
    XCircle,
    Loader2,
    Search,
    Compass,
    Sparkles,
    Maximize2
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { Input } from '../ui/input';
import { toast } from 'sonner';
import { useSocket } from '../../context/SocketContext';
import { useBusinessStore } from '../../lib/businessStore';
import { format } from 'date-fns';
import ReactMarkdown from 'react-markdown';

export function InnovationBridgeWidget() {
    const [problem, setProblem] = useState('');
    const { jobs, isLoading, fetchJobs, createJob } = useBusinessStore();
    const { socket } = useSocket();
    const [selectedJobId, setSelectedJobId] = useState<string | null>(null);

    const innovationJobs = useMemo(() => jobs.filter(j => j.type === 'innovation_bridge'), [jobs]);

    useEffect(() => {
        fetchJobs('innovation_bridge');
    }, [fetchJobs]);

    useEffect(() => {
        if (!socket) return;

        const handleJobUpdate = (data: { jobId: string, status: string }) => {
            fetchJobs('innovation_bridge');
            if (data.status === 'completed') {
                toast.success("Innovációs kutatás sikeresen befejeződött!", {
                    icon: <Sparkles className="w-4 h-4 text-yellow-500" />
                });
            } else if (data.status === 'failed') {
                toast.error("A kutatás során hiba történt.");
            }
        };

        socket.on('business_job:updated', handleJobUpdate);
        return () => {
            socket.off('business_job:updated', handleJobUpdate);
        };
    }, [socket, fetchJobs]);

    const handleStartResearch = async () => {
        if (!problem.trim()) {
            toast.error("Kérlek írd le a problémát, amire megoldást keresel!");
            return;
        }

        const jobId = await createJob('innovation_bridge', problem);
        if (jobId) {
            toast.info("A híd építése megkezdődött... Absztrahálom a problémát.");
            setProblem('');
        }
    };

    const activeJob = jobs.find(j => j.id === selectedJobId) || innovationJobs[0];
    const report = activeJob?.results_json ? JSON.parse(activeJob.results_json) : null;

    return (
        <Card className="w-full shadow-2xl border-yellow-500/20 bg-card/50 backdrop-blur-md">
            <CardHeader className="pb-3 border-b border-white/5">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-yellow-500/10 rounded-full">
                            <Lightbulb className="w-5 h-5 text-yellow-500" />
                        </div>
                        <div>
                            <CardTitle>Innovation Bridge</CardTitle>
                            <CardDescription>Keresztiparágú tudástranszfer és TRIZ absztrakció</CardDescription>
                        </div>
                    </div>
                </div>
            </CardHeader>
            <CardContent className="pt-6">
                <div className="flex gap-2 mb-8">
                    <Input 
                        placeholder="Milyen üzleti/technikai problémát oldjunk meg? (pl. Várótermi torlódás)" 
                        value={problem}
                        onChange={(e) => setProblem(e.target.value)}
                        className="bg-secondary/20 border-yellow-500/10 focus:border-yellow-500/40 h-12"
                        onKeyPress={(e) => e.key === 'Enter' && handleStartResearch()}
                    />
                    <Button 
                        onClick={handleStartResearch} 
                        disabled={isLoading}
                        className="bg-yellow-600 hover:bg-yellow-700 min-w-[160px] text-white h-12 font-bold uppercase tracking-widest text-xs"
                    >
                        {isLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Compass className="w-4 h-4 mr-2" />}
                        Híd Építése
                    </Button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                    {/* Előzmények */}
                    <div className="lg:col-span-1 border-r border-white/5 pr-4 flex flex-col gap-4">
                        <h3 className="text-[10px] font-black uppercase text-zinc-500 tracking-tighter flex items-center gap-2">
                            <History size={12} />
                            Korábbi Kutatások
                        </h3>
                        <ScrollArea className="h-[500px]">
                            <div className="space-y-2">
                                {innovationJobs.length === 0 ? (
                                    <p className="text-[10px] text-zinc-600 italic">Nincsenek korábbi jelentések.</p>
                                ) : (
                                    innovationJobs.map((job) => (
                                        <div 
                                            key={job.id}
                                            onClick={() => setSelectedJobId(job.id)}
                                            className={`p-4 rounded-xl border cursor-pointer transition-all ${
                                                selectedJobId === job.id || (!selectedJobId && innovationJobs[0].id === job.id)
                                                    ? 'bg-yellow-500/10 border-yellow-500/30' 
                                                    : 'bg-white/5 border-transparent hover:border-yellow-500/20'
                                            }`}
                                        >
                                            <div className="font-bold text-[11px] leading-tight mb-2 line-clamp-2">{job.query}</div>
                                            <div className="flex justify-between items-center">
                                                <span className="text-[9px] text-zinc-500 font-mono">
                                                    {format(new Date(job.created_at), 'MM.dd HH:mm')}
                                                </span>
                                                {job.status === 'completed' ? (
                                                    <CheckCircle2 size={12} className="text-yellow-500" />
                                                ) : (
                                                    <Loader2 size={12} className="text-blue-500 animate-spin" />
                                                )}
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </ScrollArea>
                    </div>

                    {/* Riport Megjelenítés */}
                    <div className="lg:col-span-3 min-h-[500px] flex flex-col">
                        {activeJob ? (
                            <div className="space-y-6 flex-1 flex flex-col">
                                {activeJob.status === 'running' ? (
                                    <div className="flex-1 flex flex-col items-center justify-center py-20 text-zinc-500">
                                        <div className="relative mb-8">
                                            <Loader2 size={64} className="animate-spin text-yellow-500/20" />
                                            <Sparkles className="absolute inset-0 m-auto w-8 h-8 text-yellow-500 animate-pulse" />
                                        </div>
                                        <h4 className="text-lg font-black text-white mb-2">A Híd Építése Folyamatban...</h4>
                                        <p className="text-sm max-w-sm text-center italic">"Az MI most absztrahálja a problémádat és analógiákat keres a világ távoli pontjairól."</p>
                                    </div>
                                ) : report ? (
                                    <ScrollArea className="flex-1 pr-6">
                                        <div className="prose prose-invert prose-yellow max-w-none">
                                            <div className="mb-8 p-6 rounded-2xl bg-yellow-500/5 border border-yellow-500/10 relative overflow-hidden">
                                                <div className="absolute top-0 right-0 p-4 opacity-10">
                                                    <Maximize2 size={80} />
                                                </div>
                                                <h3 className="text-yellow-500 font-black uppercase text-xs tracking-widest mt-0 mb-4">TRIZ Absztrakció</h3>
                                                <p className="text-xl font-medium leading-relaxed">{report.problem.abstractChallenge}</p>
                                                <div className="flex gap-2 mt-4 flex-wrap">
                                                    {report.problem.trizPrinciples.map((p: any) => (
                                                        <Badge key={p.id} variant="outline" className="bg-yellow-500/10 text-yellow-200 border-yellow-500/20 text-[10px]">
                                                            #{p.id} {p.name}
                                                        </Badge>
                                                    ))}
                                                </div>
                                            </div>

                                            <div className="space-y-8">
                                                <h3 className="text-white font-black uppercase text-xs tracking-widest border-b border-white/5 pb-2">Keresztiparágú Megoldások</h3>
                                                {report.solutions.map((sol: any, i: number) => (
                                                    <div key={i} className="group relative pl-8 border-l-2 border-yellow-500/20 hover:border-yellow-500/50 transition-colors py-2">
                                                        <div className="absolute -left-[9px] top-4 w-4 h-4 rounded-full bg-zinc-900 border-2 border-yellow-500 flex items-center justify-center">
                                                            <div className="w-1.5 h-1.5 rounded-full bg-yellow-500 group-hover:scale-150 transition-transform" />
                                                        </div>
                                                        <div className="flex justify-between items-start mb-2">
                                                            <h4 className="text-lg font-bold text-yellow-400 m-0">{sol.sourceIndustry}</h4>
                                                            <Badge className="bg-white/5 text-zinc-400 font-mono text-[9px]">{sol.confidence}% MATCH</Badge>
                                                        </div>
                                                        <div className="text-zinc-300 text-sm leading-relaxed mb-4">
                                                            {sol.solutionDescription}
                                                        </div>
                                                        <div className="p-4 rounded-xl bg-primary/5 border border-primary/10">
                                                            <div className="text-[10px] font-bold text-primary uppercase tracking-wider mb-1 flex items-center gap-2">
                                                                <ArrowRight size={10} /> Adaptáció nálad
                                                            </div>
                                                            <p className="text-zinc-200 text-sm italic m-0">"{sol.applicability}"</p>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </ScrollArea>
                                ) : (
                                    <div className="flex-1 flex flex-col items-center justify-center text-zinc-600 opacity-40 py-20">
                                        <XCircle size={48} className="mb-4" />
                                        <p>Hiba a riport betöltésekor.</p>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="flex-1 flex flex-col items-center justify-center text-zinc-600 opacity-40 py-20">
                                <Maximize2 size={64} className="mb-6" />
                                <h4 className="text-xl font-bold">Innovation Space</h4>
                                <p className="text-sm">Írj le egy problémát és nyomd meg a "Híd Építése" gombot.</p>
                            </div>
                        )}
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}

