                                        </div>
                                        <h4 className="text-lg font-black text-white mb-2">A Híd Építése Folyamatban...</h4>
                                        <p className="text-sm max-w-sm text-center italic">"Az MI most absztrahálja a problémádat és analógiákat keres a világ távoli pontjairól."</p>
                                    </div>
                                ) : report ? (
                                    <ScrollArea className="flex-1 pr-6">
                                        <div className="prose prose-invert prose-yellow max-w-none">
                                            <div className="mb-8 p-6 rounded-2xl bg-yellow-500/5 border border-yellow-500/10 relative overflow-hidden">
                                                <div className="absolute top-0 right-0 p-4 opacity-10">
                                                    <Maximize2 size={80} />
                                                </div>
                                                <h3 className="text-yellow-500 font-black uppercase text-xs tracking-widest mt-0 mb-4">TRIZ Absztrakció</h3>
                                                <p className="text-xl font-medium leading-relaxed">{report.problem.abstractChallenge}</p>
                                                <div className="flex gap-2 mt-4 flex-wrap">
                                                    {report.problem.trizPrinciples.map((p: any) => (
                                                        <Badge key={p.id} variant="outline" className="bg-yellow-500/10 text-yellow-200 border-yellow-500/20 text-[10px]">
                                                            #{p.id} {p.name}
                                                        </Badge>
                                                    ))}
                                                </div>
                                            </div>

                                            <div className="space-y-8">
                                                <h3 className="text-white font-black uppercase text-xs tracking-widest border-b border-white/5 pb-2">Keresztiparágú Megoldások</h3>
                                                {report.solutions.map((sol: any, i: number) => (
                                                    <div key={i} className="group relative pl-8 border-l-2 border-yellow-500/20 hover:border-yellow-500/50 transition-colors py-2">
                                                        <div className="absolute -left-[9px] top-4 w-4 h-4 rounded-full bg-zinc-900 border-2 border-yellow-500 flex items-center justify-center">
                                                            <div className="w-1.5 h-1.5 rounded-full bg-yellow-500 group-hover:scale-150 transition-transform" />
                                                        </div>
                                                        <div className="flex justify-between items-start mb-2">
                                                            <h4 className="text-lg font-bold text-yellow-400 m-0">{sol.sourceIndustry}</h4>
                                                            <Badge className="bg-white/5 text-zinc-400 font-mono text-[9px]">{sol.confidence}% MATCH</Badge>
                                                        </div>
                                                        <div className="text-zinc-300 text-sm leading-relaxed mb-4">
                                                            {sol.solutionDescription}
                                                        </div>
                                                        <div className="p-4 rounded-xl bg-primary/5 border border-primary/10">
                                                            <div className="text-[10px] font-bold text-primary uppercase tracking-wider mb-1 flex items-center gap-2">
                                                                <ArrowRight size={10} /> Adaptáció nálad
                                                            </div>
                                                            <p className="text-zinc-200 text-sm italic m-0">"{sol.applicability}"</p>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </ScrollArea>
                                ) : (
                                    <div className="flex-1 flex flex-col items-center justify-center text-zinc-600 opacity-40 py-20">
                                        <XCircle size={48} className="mb-4" />
                                        <p>Hiba a riport betöltésekor.</p>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="flex-1 flex flex-col items-center justify-center text-zinc-600 opacity-40 py-20">
                                <Maximize2 size={64} className="mb-6" />
                                <h4 className="text-xl font-bold">Innovation Space</h4>
                                <p className="text-sm">Írj le egy problémát és nyomd meg a "Híd Építése" gombot.</p>
                            </div>
                        )}
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}

