export function NeuralLinkChat() {
  // ... (existing state variables)
  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  // ... (existing useEffects)

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(chunksRef.current, { type: 'audio/webm' });
        await handleAudioUpload(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      setIsRecording(true);
      toast.info("Hangrögzítés elindítva...");
    } catch (err) {
      toast.error("Nem sikerült elérni a mikrofont. Ellenőrizd az engedélyeket!");
      console.error(err);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleAudioUpload = async (audioBlob: Blob) => {
    setIsTranscribing(true);
    const formData = new FormData();
    formData.append('file', audioBlob, 'voice_command.webm');

    try {
      // Send to Python backend transcription endpoint
      const response = await fetch('http://localhost:8000/voice/transcribe', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        throw new Error('A hangfeldolgozás sikertelen.');
      }

      const data = await response.json();
      if (data.status === 'success' && data.text) {
        setInput(prev => prev ? `${prev} ${data.text}` : data.text);
        toast.success("Beszéd felismerve!", {
          icon: <Microphone size={16} />
        });
      }
    } catch (err: any) {
      toast.error(`Hiba a hangfelismerés során: ${err.message}`);
    } finally {
      setIsTranscribing(false);
    }
  };

  // ... (rest of the component until the input area)

