                        >
                          <span
                            className={`w-1.5 h-1.5 rounded-full ${msg.thoughts ? "bg-amber-500 animate-pulse" : "bg-zinc-500"}`}
                          />
                          {expandedThoughts[i] ? "Hide Intel" : "Show Intel"}
                          {msg.executedBy && (
                            <span className="opacity-50 ml-2">
