              </SelectContent>
            </Select>
          )}
        </div>
        <div className="flex items-center gap-1">
          {showBrowser && (
            <Button 
              variant="ghost" 
              size="icon" 
              onClick={() => setBrowserTimestamp(Date.now())} 
              title="Képernyő frissítése"
              className="text-zinc-400 hover:text-primary"
            >
              <ArrowsClockwise size={16} className={isLoading ? "animate-spin" : ""} />
