import { config } from '../config/index.js';
import { logWarn } from './logger.js';

let db: any = null;
let path: any = null;
let fs: any = null;

export interface DbMessage {
    role: string;
    content: string;
    is_log: number;
    timestamp: string;
}

async function ensureDeps() {
    if (typeof process !== 'undefined' && process.versions?.node) {
        if (!path) path = await import('path');
        if (!fs) fs = await import('fs');
    }
}

async function getDb() {
    if (db) return db;

    await ensureDeps();

    // If not in Node or imports failed, return null
    if (!path || !fs) return null;

    try {
        if (!fs.existsSync(config.systemLogDir)) {
            fs.mkdirSync(config.systemLogDir, { recursive: true });
        }

        const dbPath = path.join(config.systemLogDir, 'brunella.db');
        // console.log('DEBUG: DB Path:', dbPath); // Optional logging

        const Database = (await import('better-sqlite3')).default;
        db = new Database(dbPath);

        // Auto-initialize tables on first load
        _initTables(db);

        return db;
    } catch (e: any) {
        logWarn('System', `Failed to initialize SQLite database: ${e.message}`);
        return null;
    }
}

function _initTables(database: any) {
    database.exec(`
        CREATE TABLE IF NOT EXISTS chats (
            id TEXT PRIMARY KEY,
            title TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    `);

    database.exec(`
        CREATE TABLE IF NOT EXISTS messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chat_id TEXT,
            role TEXT,
            content TEXT,
            is_log INTEGER DEFAULT 0,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(chat_id) REFERENCES chats(id)
        )
    `);

    database.exec(`
        CREATE TABLE IF NOT EXISTS tasks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id INTEGER,
            agent_name TEXT,
            description TEXT,
            context TEXT,
            status TEXT DEFAULT 'pending',
            result TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(parent_id) REFERENCES tasks(id)
        )
    `);

    database.exec(`
        CREATE TABLE IF NOT EXISTS business_jobs (
            id TEXT PRIMARY KEY,
            type TEXT, -- e.g., 'lead_mining', 'invoice_sync'
            status TEXT DEFAULT 'pending',
            query TEXT,
            results_json TEXT,
            metadata TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    `);
}

// Public API - Async wrappers

export async function initDb() {
    await getDb();
}

export async function saveBusinessJob(job: { id: string, type: string, query: string, metadata?: string }) {
    const database = await getDb();
    if (!database) return null;

    const stmt = database.prepare('INSERT INTO business_jobs (id, type, query, metadata) VALUES (?, ?, ?, ?)');
    stmt.run(job.id, job.type, job.query, job.metadata || null);
    return job.id;
}

export async function getBusinessJobs(limit: number = 20, type?: string) {
    const database = await getDb();
    if (!database) return [];

    let query = 'SELECT * FROM business_jobs';
    const params: any[] = [];

    if (type) {
        query += ' WHERE type = ?';
        params.push(type);
    }

    query += ' ORDER BY created_at DESC LIMIT ?';
    params.push(limit);

    const stmt = database.prepare(query);
    return stmt.all(...params);
}

export async function updateBusinessJobStatus(id: string, status: string, resultsJson?: string) {
    const database = await getDb();
    if (!database) return;

    const stmt = database.prepare('UPDATE business_jobs SET status = ?, results_json = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?');
    stmt.run(status, resultsJson || null, id);
}

export async function saveMessage(chatId: string, role: string, content: string, isLog: boolean = false) {
    const database = await getDb();
    if (!database) return;

    const stmtChat = database.prepare('INSERT OR IGNORE INTO chats (id) VALUES (?)');
    stmtChat.run(chatId);

    const stmt = database.prepare('INSERT INTO messages (chat_id, role, content, is_log) VALUES (?, ?, ?, ?)');
    stmt.run(chatId, role, content, isLog ? 1 : 0);
}

export async function getMessages(chatId: string): Promise<DbMessage[]> {
    const database = await getDb();
    if (!database) return [];

    const stmt = database.prepare('SELECT role, content, is_log, timestamp FROM messages WHERE chat_id = ? ORDER BY timestamp ASC');
    return stmt.all(chatId) as DbMessage[];
}

export async function createChat(id: string, title: string) {
    const database = await getDb();
    if (!database) return;

    const stmt = database.prepare('INSERT OR IGNORE INTO chats (id, title) VALUES (?, ?)');
    stmt.run(id, title);
}

export async function saveTask(task: { agent_name: string, description: string, context?: string, parent_id?: number }) {
    const database = await getDb();
    if (!database) return null;

    const stmt = database.prepare('INSERT INTO tasks (agent_name, description, context, parent_id) VALUES (?, ?, ?, ?)');
    const result = stmt.run(task.agent_name, task.description, task.context || null, task.parent_id || null);
    return result.lastInsertRowid;
}

export async function updateTaskStatus(id: number | bigint, status: string, result?: string) {
    const database = await getDb();
    if (!database) return;

    const stmt = database.prepare('UPDATE tasks SET status = ?, result = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?');
    stmt.run(status, result || null, id);
}

export async function getTasks(limit: number = 50, offset: number = 0) {
    const database = await getDb();
    if (!database) return [];

    const stmt = database.prepare('SELECT * FROM tasks ORDER BY created_at DESC LIMIT ? OFFSET ?');
    return stmt.all(limit, offset);
}

export async function getTaskCount() {
    const database = await getDb();
    if (!database) return 0;

    const stmt = database.prepare('SELECT COUNT(*) as count FROM tasks');
    return (stmt.get() as any).count;
}

#!/usr/bin/env python3
"""
Brunella Incubator - Golden Dataset Manager
ChatML format training data collection for fine-tuning
"""

import json
import os
from datetime import datetime
from typing import Dict, Any, List, Optional
from pathlib import Path

TRAINING_DATA_PATH = "data/training/golden_dataset.jsonl"


class DatasetManager:
    """Manages Brunella's Golden Dataset for fine-tuning"""
    
    @staticmethod
    def ensure_directories():
        """Create required directories"""
        Path(TRAINING_DATA_PATH).parent.mkdir(parents=True, exist_ok=True)
    
    @staticmethod
    def save_gold_sample(
        system_prompt: str,
        user_input: str,
        assistant_output: Any,
        source: str = "unknown",
        quality_score: float = 1.0,
        metadata: Optional[Dict[str, Any]] = None
    ) -> bool:
        """
        Save successful interaction to training dataset in ChatML format
        
        Args:
            system_prompt: System prompt
            user_input: User input
            assistant_output: Model output (dict or str)
            source: Data source (default: "unknown")
            quality_score: Quality score 0.0-1.0 (default: 1.0)
            metadata: Additional metadata
        
        Returns:
            bool: True on success, False on error
        """
        try:
            DatasetManager.ensure_directories()
            
            # Convert output to string if needed
            if isinstance(assistant_output, dict):
                assistant_content = json.dumps(assistant_output, ensure_ascii=False)
            else:
                assistant_content = str(assistant_output)
            
            entry = {
                "messages": [
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_input},
                    {"role": "assistant", "content": assistant_content}
                ],
                "metadata": {
                    "timestamp": datetime.utcnow().isoformat(),
                    "source": source,
                    "quality_score": quality_score,
                    "client_version": "1.0"
                }
            }
            
            # Add extra metadata if provided
            if metadata:
                entry["metadata"].update(metadata)
            
            with open(TRAINING_DATA_PATH, "a", encoding="utf-8") as f:
                f.write(json.dumps(entry, ensure_ascii=False) + "\n")
            
            return True
        except Exception as e:
            print(f"❌ Error saving sample: {e}")
            return False
    
    @staticmethod
    def get_dataset_stats() -> Dict[str, Any]:
        """
        Get dataset statistics
        
        Returns:
            dict: {total_samples, sources, avg_quality, file_size_mb, status}
        """
        DatasetManager.ensure_directories()
        
        if not os.path.exists(TRAINING_DATA_PATH):
            return {
                "total_samples": 0,
                "sources": {},
                "avg_quality": 0.0,
                "file_size_mb": 0.0,
                "status": "EMPTY"
            }
        
        try:
            samples = []
            sources = {}
            quality_scores = []
            
            with open(TRAINING_DATA_PATH, "r", encoding="utf-8") as f:
                for line in f:
                    if line.strip():
                        try:
                            entry = json.loads(line)
                            samples.append(entry)
                            
                            source = entry.get("metadata", {}).get("source", "unknown")
                            sources[source] = sources.get(source, 0) + 1
                            
                            quality = entry.get("metadata", {}).get("quality_score", 1.0)
                            quality_scores.append(quality)
                        except json.JSONDecodeError:
                            pass
            
            total = len(samples)
            avg_quality = sum(quality_scores) / len(quality_scores) if quality_scores else 0.0
            file_size = os.path.getsize(TRAINING_DATA_PATH) / 1024 / 1024  # MB
            
            # Determine status
            if total == 0:
                status = "EMPTY"
            elif total < 5:
                status = f"BUILDING ({total}/5 min)"
            elif total < 100:
                status = "GROWING"
            else:
                status = "READY"
            
            return {
                "total_samples": total,
                "sources": sources,
                "avg_quality": round(avg_quality, 2),
                "file_size_mb": round(file_size, 2),
                "status": status
            }
        except Exception as e:
            print(f"❌ Error reading data: {e}")
            return {
                "total_samples": 0,
                "sources": {},
                "avg_quality": 0.0,
                "file_size_mb": 0.0,
                "status": "ERROR"
            }
    
    @staticmethod
    def load_dataset_for_training(max_samples: Optional[int] = None):
        """
        Load dataset in HuggingFace Dataset format for Unsloth training
        
        Args:
            max_samples: Maximum samples to load (None = all)
        
        Returns:
            Dataset or None
        """
        try:
            from datasets import Dataset
            
            if not os.path.exists(TRAINING_DATA_PATH):
                print(f"⚠️ File not found: {TRAINING_DATA_PATH}")
                return None
            
            samples = []
            with open(TRAINING_DATA_PATH, "r", encoding="utf-8") as f:
                for i, line in enumerate(f):
                    if max_samples and i >= max_samples:
                        break
                    if line.strip():
                        try:
                            samples.append(json.loads(line))
                        except json.JSONDecodeError:
                            pass
            
            if not samples:
                print("⚠️ No sample data in dataset")
                return None
            
            # Convert to HuggingFace Dataset
            dataset = Dataset.from_dict({
                "text": [
                    DatasetManager._format_chatml(s.get("messages", [])) 
                    for s in samples
                ]
            })
            
            return dataset
        except ImportError:
            print("❌ HuggingFace datasets not installed: pip install datasets")
            return None
        except Exception as e:
            print(f"❌ Error loading data: {e}")
            return None
    
    @staticmethod
    def _format_chatml(messages: List[Dict[str, str]]) -> str:
        """Format ChatML messages to string"""
        formatted = ""
        for msg in messages:
            role = msg.get("role", "user")
            content = msg.get("content", "")
            formatted += f"<|im_start|>{role}\n{content}\n<|im_end|>\n"
        return formatted
    
    @staticmethod
    def clear_dataset(force: bool = False) -> bool:
        """
        Safely delete the dataset
        
        Args:
            force: Skip confirmation
        
        Returns:
            bool: True on success, False on error
        """
        try:
            if not os.path.exists(TRAINING_DATA_PATH):
                return True
            
            if not force:
                print(f"⚠️ Will delete all data: {TRAINING_DATA_PATH}")
                confirm = input("Are you sure? (y/n): ").lower()
                if confirm != 'y':
                    print("❌ Delete cancelled")
                    return False
            
            os.remove(TRAINING_DATA_PATH)
            print("✅ Dataset deleted")
            return True
        except Exception as e:
            print(f"❌ Error deleting: {e}")
            return False


# ===== CLI INTERFACE =====

def cli_stats():
    """Display statistics from CLI"""
    stats = DatasetManager.get_dataset_stats()
    print("\n" + "="*50)
    print("📊 DATASET STATISTICS")
    print("="*50)
    print(f"Status: {stats['status']}")
    print(f"Total samples: {stats['total_samples']}")
    print(f"Average quality: {stats['avg_quality']}")
    print(f"File size: {stats['file_size_mb']} MB")
    if stats['sources']:
        print("\nSources:")
        for source, count in stats['sources'].items():
            print(f"  - {source}: {count}")
    print("="*50 + "\n")


def cli_test():
    """Test with 3 sample entries from CLI"""
    print("\n🧪 TEST: Saving 3 samples")
    print("="*50)
    
    samples = [
        {
            "system": "You are a helpful AI assistant.",
            "user": "What is Python?",
            "output": "Python is a high-level programming language.",
            "source": "test_sample_1"
        },
        {
            "system": "You are a data extraction expert.",
            "user": "<HTML><p>Test content</p></HTML>",
            "output": {"extracted": "Test content", "type": "html"},
            "source": "test_sample_2"
        },
        {
            "system": "You are a JSON validator.",
            "user": '{"key": "value"}',
            "output": {"valid": True, "format": "json"},
            "source": "test_sample_3"
        }
    ]
    
    for i, sample in enumerate(samples, 1):
        result = DatasetManager.save_gold_sample(
            system_prompt=sample["system"],
            user_input=sample["user"],
            assistant_output=sample["output"],
            source=sample["source"],
            quality_score=1.0
        )
        status = "✅ OK" if result else "❌ FAIL"
        print(f"[{i}/3] {sample['source']} → {status}")
    
    print("="*50)
    cli_stats()


def cli_clear():
    """Delete dataset from CLI"""
    DatasetManager.clear_dataset(force=False)


# ===== Top-level API (for easy integration) =====

def save_gold_sample(
    system_prompt: Optional[str] = None,
    user_input: Optional[str] = None,
    assistant_output: Optional[Any] = None,
    source: str = "unknown",
    quality_score: float = 1.0,
    metadata: Optional[Dict[str, Any]] = None,
    **kwargs: Any,
) -> bool:
    """
    Backward-compatible top-level alias for DatasetManager.save_gold_sample.

    Supports both calling styles:
      1) save_gold_sample(system_prompt=..., user_input=..., assistant_output=...)
      2) save_gold_sample(prompt=..., completion=..., source=..., quality=...)
    """
    prompt = kwargs.get("prompt")
    completion = kwargs.get("completion")
    quality = kwargs.get("quality")

    resolved_system_prompt = system_prompt or kwargs.get(
        "system", "You are a helpful AI assistant."
    )
    resolved_user_input = user_input if user_input is not None else prompt
    resolved_assistant_output = (
        assistant_output if assistant_output is not None else completion
    )
    resolved_quality = quality_score if quality is None else float(quality)

    if resolved_user_input is None or resolved_assistant_output is None:
        return False

    return DatasetManager.save_gold_sample(
        resolved_system_prompt,
        resolved_user_input,
        resolved_assistant_output,
        source,
        resolved_quality,
        metadata,
    )

def get_dataset_stats() -> Dict[str, Any]:
    """Top-level alias for DatasetManager.get_dataset_stats"""
    return DatasetManager.get_dataset_stats()


# ===== MAIN =====

if __name__ == "__main__":
    import sys
    
    if len(sys.argv) > 1:
        cmd = sys.argv[1]
        if cmd == "stats":
            cli_stats()
        elif cmd == "test":
            cli_test()
        elif cmd == "clear":
            cli_clear()
        else:
            print(f"Unknown command: {cmd}")
            print("Available: stats, test, clear")
    else:
        # Default: show stats
        cli_stats()

