import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { google } from 'googleapis';
import { getGoogleAuth } from '../utils/googleAuth.js';
import { getBusinessJobs } from '../utils/db.js';

export function registerGoogleWorkspaceTools(server: McpServer) {

    // ... (previous tools remain the same) ...

    // BUSINESS: Export Job to Sheets
    server.tool(
        "business_export_to_sheets",
        "Exports a completed business job's results to a new Google Sheet.",
        {
            jobId: z.string(),
            title: z.string().optional(),
        },
        async ({ jobId, title }) => {
            try {
                // 1. Fetch job results from DB
                const jobs = await getBusinessJobs(1); // Generic get by ID would be better, but we can filter
                const job = (await getBusinessJobs(100)).find((j: any) => j.id === jobId);

                if (!job || !job.results_json) {
                    return { isError: true, content: [{ type: "text", text: `Job not found or has no results: ${jobId}` }] };
                }

                const data = JSON.parse(job.results_json);
                if (!Array.isArray(data) || data.length === 0) {
                    return { isError: true, content: [{ type: "text", text: `Job results are empty or invalid.` }] };
                }

                const auth = await getGoogleAuth();
                const sheets = google.sheets({ version: 'v4', auth });

                // 2. Create Spreadsheet
                const createRes = await sheets.spreadsheets.create({
                    requestBody: {
                        properties: { title: title || `BAS Export: ${job.query} (${job.type})` }
                    }
                });

                const spreadsheetId = createRes.data.spreadsheetId!;
                const spreadsheetUrl = createRes.data.spreadsheetUrl!;

                // 3. Prepare Data (Headers + Rows)
                const headers = Object.keys(data[0]);
                const rows = data.map(item => headers.map(h => String(item[h] || '')));
                const values = [headers, ...rows];

                // 4. Append Data
                await sheets.spreadsheets.values.append({
                    spreadsheetId,
                    range: "Sheet1!A1",
                    valueInputOption: 'RAW',
                    requestBody: { values },
                });

                return {
                    content: [{ 
                        type: "text", 
                        text: `Sikeresen exportálva! Táblázat elérhető itt: ${spreadsheetUrl}` 
                    }]
                };
            } catch (e: any) {
                return { isError: true, content: [{ type: "text", text: `Export Error: ${e.message}` }] };
            }
        }
    );

    // GMAIL: List Messages
    server.tool(
        "gmail_list_messages",
        "Lists recent emails from Gmail.",
        {
            maxResults: z.number().default(10),
        },
        async ({ maxResults }) => {
            try {
                const auth = await getGoogleAuth();
                const gmail = google.gmail({ version: 'v1', auth });
                const res = await gmail.users.messages.list({ userId: 'me', maxResults });

                const messages = res.data.messages || [];
                const details = await Promise.all(messages.map(async (msg) => {
                    const m = await gmail.users.messages.get({ userId: 'me', id: msg.id! });
                    return {
                        id: msg.id,
                        snippet: m.data.snippet,
                        from: m.data.payload?.headers?.find(h => h.name === 'From')?.value
                    };
                }));

                return {
                    content: [{ type: "text", text: JSON.stringify(details, null, 2) }]
                };
            } catch (e: any) {
                return { isError: true, content: [{ type: "text", text: `Gmail Error: ${e.message}` }] };
            }
        }
    );

    // CALENDAR: List Events
    server.tool(
        "calendar_list_events",
        "Lists upcoming events from Google Calendar.",
        {
            maxResults: z.number().default(10),
        },
        async ({ maxResults }) => {
            try {
                const auth = await getGoogleAuth();
                const calendar = google.calendar({ version: 'v3', auth });
                const res = await calendar.events.list({
                    calendarId: 'primary',
                    timeMin: (new Date()).toISOString(),
                    maxResults,
                    singleEvents: true,
                    orderBy: 'startTime',
                });

                const events = res.data.items || [];
                const formatted = events.map(e => ({
                    summary: e.summary,
                    start: e.start?.dateTime || e.start?.date,
                    location: e.location
                }));

                return {
                    content: [{ type: "text", text: JSON.stringify(formatted, null, 2) }]
                };
            } catch (e: any) {
                return { isError: true, content: [{ type: "text", text: `Calendar Error: ${e.message}` }] };
            }
        }
    );

    // SHEETS: Append Data
    server.tool(
        "sheets_append_data",
        "Appends rows of data to a Google Sheet.",
        {
            spreadsheetId: z.string(),
            range: z.string().default("Sheet1!A1"),
            values: z.array(z.array(z.any())),
        },
        async ({ spreadsheetId, range, values }) => {
            try {
                const auth = await getGoogleAuth();
                const sheets = google.sheets({ version: 'v4', auth });
                const res = await sheets.spreadsheets.values.append({
                    spreadsheetId,
                    range,
                    valueInputOption: 'RAW',
                    requestBody: { values },
                });

                return {
                    content: [{ type: "text", text: `Success: Updated ${res.data.updates?.updatedCells} cells.` }]
                };
            } catch (e: any) {
                return { isError: true, content: [{ type: "text", text: `Sheets Error: ${e.message}` }] };
            }
        }
    );

    // SHEETS: Create Spreadsheet
    server.tool(
        "sheets_create_spreadsheet",
        "Creates a new Google Sheet.",
        {
            title: z.string(),
        },
        async ({ title }) => {
            try {
                const auth = await getGoogleAuth();
                const sheets = google.sheets({ version: 'v4', auth });
                const res = await sheets.spreadsheets.create({
                    requestBody: {
                        properties: { title }
                    }
                });

                return {
                    content: [{ type: "text", text: JSON.stringify({
                        spreadsheetId: res.data.spreadsheetId,
                        spreadsheetUrl: res.data.spreadsheetUrl
                    }, null, 2) }]
                };
            } catch (e: any) {
                return { isError: true, content: [{ type: "text", text: `Sheets Error: ${e.message}` }] };
            }
        }
    );
}

