      }

      // 2. Generate Application Files
      const systemPrompt = `You are the Brunella Studio Architect. 
Your task is to generate the COMPLETE source code for a web application based on the user's description.
- Use React, TypeScript, and Tailwind CSS.
- Output multiple files if needed using a JSON format: { "files": [ { "path": "src/App.tsx", "content": "..." } ] }
- Focus on modern, high-quality UI (Lucide icons, Glassmorphism).
- Ensure App.tsx is the entry point.`;

      const prompt = `Application Description: ${task}
Project Root: ${rootDir}
Generate the necessary files to make this app functional and beautiful.`;

