      const previewUrl = await studioRunner.startProject(projectId, rootDir);

      return {
        status: "success",
        message: "Application scaffolded and kódolás elindítva.",
        data: { previewUrl }
      };
    } catch (e: any) {
      logError(this.name, `Studio error: ${e.message}`);
      return { status: "error", error: e.message };
    }
  }

