import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { logInfo } from '../utils/logger.js';
import { generateResponse } from '../core/llm_client.js';

export class UXDesignerAgent extends BaseAgent {
    name = "UX Designer";
    description = "Expert in UI/UX design, design systems, and visual aesthetics. Generates component blueprints and CSS styling guides.";
    role = "UI/UX Specialist";
    capabilities = ["design_spec_generation", "component_blueprint", "wireframe_creation"];

    private llmProvider = process.env.LLM_PROVIDER || "github";

    async executeTask(context: AgentContext): Promise<AgentResult> {
        const { task } = context;
        logInfo(this.name, `Designing UI components for: ${task}`);

        const systemPrompt = `You are a world-class UI/UX Designer.
Your task is to provide a detailed visual and structural specification for a React component or page.
- Focus on clean typography, white space, and professional color palettes.
- Use Tailwind CSS class names in your suggestions.
- Provide a clear layout structure (Header, Main, Sidebar, Footer).
- Mention specific Lucide icons to use.`;

        const prompt = `Application Goal: ${task}
Create a high-fidelity UX specification that a developer can implement easily.`;

        const designSpec = await generateResponse(prompt, this.llmProvider, "gpt-4o");

        return {
            success: true,
            message: "UI/UX Design Spec generálva.",
            data: { designSpec }
        };
    }
}

